import{_ as i,C as a,o as r,c,j as t,a as o,E as n,a2 as p,w as h}from"./chunks/framework.B-bxTAy7.js";const E=JSON.parse('{"title":"05 · GPIO 与按键","description":"","frontmatter":{"title":"05 · GPIO 与按键"},"headers":[],"relativePath":"embedded/gpio.md","filePath":"embedded/gpio.md","lastUpdated":1792416913000}'),g={name:"embedded/gpio.md"};function d(y,s,k,u,v,b){const l=a("Meta"),e=a("GpioModeDemo"),m=a("DemoBox");return r(),c("div",null,[s[0]||(s[0]=t("h1",{id:"_05-·-gpio-与按键",tabindex:"-1"},[o("05 · GPIO 与按键 "),t("a",{class:"header-anchor",href:"#_05-·-gpio-与按键","aria-label":'Permalink to "05 · GPIO 与按键"'},"​")],-1)),n(l,{time:"35 min",level:"核心",note:"最基础的引脚：八种模式怎么选、上下拉为什么必须有、按键为什么要消抖"}),s[1]||(s[1]=p('<h2 id="结论先行" tabindex="-1">结论先行 <a class="header-anchor" href="#结论先行" aria-label="Permalink to &quot;结论先行&quot;">​</a></h2><ol><li><strong>GPIO 有八种工作模式</strong>：输入（浮空 / 上拉 / 下拉 / 模拟）、输出（推挽 / 开漏）、复用（推挽 / 开漏）。<strong>模式选错，引脚就完全不按预期工作</strong>。</li><li><strong>推挽能主动输出高低电平；开漏只能拉低，输出「高」其实是释放引脚</strong>，必须外部上拉才有高电平——这是 I²C 总线的物理基础。</li><li><strong>输入引脚绝不允许悬空</strong>：浮空输入 + 外部悬空 = 电平随机跳变。按键、拨码开关这类「可能断开」的输入必须配上拉或下拉。</li><li><strong>机械按键会抖动（5~20 ms），必须消抖</strong>，否则一次按下会被读成好几次。</li><li><strong>IO 驱动能力有限</strong>（单脚约 20 mA 量级），驱动继电器、电机、大功率 LED 必须用三极管或 MOS 管。</li></ol><h2 id="一、八种模式" tabindex="-1">一、八种模式 <a class="header-anchor" href="#一、八种模式" aria-label="Permalink to &quot;一、八种模式&quot;">​</a></h2><p>STM32F1 用 <code>CRL</code>（管 Pin0~7）/ <code>CRH</code>（管 Pin8~15）里的 4 位配置每根引脚：2 位 <code>MODE</code>（方向+速度） + 2 位 <code>CNF</code>（具体模式）。组合出八种：</p><table tabindex="0"><thead><tr><th>大类</th><th>模式</th><th>特点</th><th>典型用途</th></tr></thead><tbody><tr><td><strong>输入</strong></td><td>浮空输入</td><td>不接上下拉，完全由外部决定</td><td>外部已有确定驱动的信号（如另一芯片的输出）</td></tr><tr><td></td><td>上拉输入</td><td>内部电阻拉到 VCC，默认 1</td><td><strong>按键（按下接地）</strong>、开漏总线的输入</td></tr><tr><td></td><td>下拉输入</td><td>内部电阻拉到 GND，默认 0</td><td>高电平有效的按键</td></tr><tr><td></td><td>模拟输入</td><td>断开数字输入缓冲，直连 ADC</td><td>ADC 采样、比较器输入</td></tr><tr><td><strong>输出</strong></td><td>推挽输出</td><td>P 管拉高、N 管拉低，都能主动驱动</td><td>驱动 LED、控制普通数字器件</td></tr><tr><td></td><td>开漏输出</td><td>只能拉低，写 1 = 释放</td><td>I²C 总线、电平转换、线与</td></tr><tr><td><strong>复用</strong></td><td>复用推挽</td><td>由片上外设驱动（推挽）</td><td>UART 的 TX、SPI 的 MOSI/SCK、TIM 的 PWM</td></tr><tr><td></td><td>复用开漏</td><td>由片上外设驱动（开漏）</td><td>I²C 的 SDA/SCL</td></tr></tbody></table><blockquote><p>F4 及以后把这 4 位拆成了几个独立寄存器，更好理解：<code>MODER</code>（输入/输出/复用/模拟）+ <code>OTYPER</code>（推挽/开漏）+ <code>OSPEEDR</code>（速度）+ <code>PUPDR</code>（无/上拉/下拉）。<strong>方向和上下拉变成正交的两个维度</strong>，可以任意组合。</p></blockquote><h2 id="二、推挽-vs-开漏-最容易混淆的一对" tabindex="-1">二、推挽 vs 开漏（最容易混淆的一对） <a class="header-anchor" href="#二、推挽-vs-开漏-最容易混淆的一对" aria-label="Permalink to &quot;二、推挽 vs 开漏（最容易混淆的一对）&quot;">​</a></h2><p><strong>推挽</strong>：内部上下两个 MOS 管，一个负责拉到 VCC，一个负责拉到 GND。写 1 就真的输出高电平，写 0 就真的输出低电平，<strong>两端都能主动驱动</strong>。</p><p><strong>开漏</strong>：只有下面那个 N 管（漏极开路，所以叫开漏）。</p><ul><li>写 <strong>0</strong> → N 管导通 → 引脚被<strong>主动拉低</strong>；</li><li>写 <strong>1</strong> → N 管关断 → 引脚<strong>悬空（高阻）</strong>，电平由外部电路决定。</li></ul>',10)),n(m,{title:"GPIO 模式演示：选模式 + 外部接法，看引脚到底是什么电平",hint:"必试四组：输入浮空+悬空（随机电平）→ 输入上拉+接地（读到 0，这就是按键）→ 输出开漏+写1+上拉（得到 1）→ 输出开漏+写1+悬空（得不到高电平）。"},{default:h(()=>[n(e)]),_:1}),s[2]||(s[2]=p(`<div class="tip custom-block"><p class="custom-block-title">例 1 · 按键电路的上拉电阻怎么取</p><p>按键一端接 MCU 引脚、另一端接地，引脚配置成<strong>上拉输入</strong>：按键松开时内部上拉把引脚拉成 1，按下时被外部短路到地读到 0。</p><p>若用外部上拉电阻，典型取 <strong>4.7 kΩ ~ 10 kΩ</strong>。以 3.3 V 供电计算按下时的电流：</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>R</mi><mo>=</mo><mn>4.7</mn><mtext> k</mtext><mi mathvariant="normal">Ω</mi><mo>:</mo><mspace width="1em"></mspace><mi>I</mi><mo>=</mo><mfrac><mn>3.3</mn><mn>4700</mn></mfrac><mo>≈</mo><mn>0.70</mn><mtext> mA</mtext></mrow><annotation encoding="application/x-tex">R = 4.7\\ \\text{k}\\Omega:\\quad I = \\frac{3.3}{4700} \\approx 0.70\\ \\text{mA} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord">4.7</span><span class="mspace"> </span><span class="mord text"><span class="mord">k</span></span><span class="mord">Ω</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">:</span><span class="mspace" style="margin-right:1em;"></span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.0074em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">4700</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">3.3</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">0.70</span><span class="mspace"> </span><span class="mord text"><span class="mord">mA</span></span></span></span></span></span><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>R</mi><mo>=</mo><mn>10</mn><mtext> k</mtext><mi mathvariant="normal">Ω</mi><mo>:</mo><mspace width="1em"></mspace><mi>I</mi><mo>=</mo><mfrac><mn>3.3</mn><mn>10000</mn></mfrac><mo>≈</mo><mn>0.33</mn><mtext> mA</mtext></mrow><annotation encoding="application/x-tex">R = 10\\ \\text{k}\\Omega:\\quad I = \\frac{3.3}{10000} \\approx 0.33\\ \\text{mA} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord">10</span><span class="mspace"> </span><span class="mord text"><span class="mord">k</span></span><span class="mord">Ω</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">:</span><span class="mspace" style="margin-right:1em;"></span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.0074em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">10000</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">3.3</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">0.33</span><span class="mspace"> </span><span class="mord text"><span class="mord">mA</span></span></span></span></span></span><p><strong>为什么不取更小</strong>：电阻越小，按键按下时白白流过的电流越大（1 kΩ 就有 3.3 mA），电池供电的产品会因此缩短续航。 <strong>为什么不取更大</strong>：电阻越大，引脚越容易受空间耦合的干扰（引脚输入阻抗很高，微弱电流就能改变电平），50 kΩ 以上就明显不可靠了。4.7 k~10 k 是功耗与抗干扰的平衡点。</p><p><strong>优先用内部上拉</strong>（<code>GPIO_PULLUP</code>）：省一个元件，且阻值由芯片保证（通常 30~50 kΩ，略大但够用）。</p></div><h2 id="三、按键为什么要消抖" tabindex="-1">三、按键为什么要消抖 <a class="header-anchor" href="#三、按键为什么要消抖" aria-label="Permalink to &quot;三、按键为什么要消抖&quot;">​</a></h2><p>机械按键在闭合/断开的瞬间，金属触点会<strong>弹跳</strong>数次才稳定，持续时间通常 <strong>5~20 ms</strong>。对运行在 MHz 级别的 MCU 来说，这段时间足够读成几十次「按下—松开」。</p><p><strong>硬件消抖</strong>：在按键两端并联一个 100 nF 电容（配合上拉电阻构成 RC 滤波），把抖动的毛刺滤平。代价是每个按键多一个电容。</p><p><strong>软件消抖</strong>（更常用）：读到电平变化后，<strong>延时 10~20 ms 再读一次</strong>，若仍保持才认为有效。但不要用死等延时（<code>HAL_Delay</code> 会阻塞整个 CPU），正确做法是<strong>用定时器定时扫描</strong>（如每 5~10 ms 扫一次按键），配合状态机：</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 每 10 ms 由定时器中断调用一次</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Key_Scan</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  static</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> uint8_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> last </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  uint8_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> now </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> HAL_GPIO_ReadPin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(KEY_GPIO_Port, KEY_Pin);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (now </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &amp;&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> last </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) key_pressed </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   // 只在「从松开变按下」时触发一次</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  last </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> now;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">例 2 · 消抖时间取多少</p><p>按键抖动一般 <strong>5~20 ms</strong>，所以消抖延时应<strong>大于最大抖动时间</strong>，取 <strong>10~20 ms</strong>。</p><ul><li>取 5 ms：可能仍在抖动窗口内，偶尔会误触发两次；</li><li>取 20 ms：可靠，但按键响应变慢（人手能察觉的下限约 50~100 ms，20 ms 无感）；</li><li><strong>定时扫描周期</strong>取 10 ms 即可：既能滤掉抖动，又保证响应及时。</li></ul><p><strong>注意「响应变慢」和「误触发」的权衡</strong>：对音量加减这类需要长按连续触发的功能，还要加「首次触发后延时 500 ms 再进入连发」的逻辑。</p></div><h2 id="四、输出速度-翻转速率-是什么" tabindex="-1">四、输出速度（翻转速率）是什么 <a class="header-anchor" href="#四、输出速度-翻转速率-是什么" aria-label="Permalink to &quot;四、输出速度（翻转速率）是什么&quot;">​</a></h2><p>配置 GPIO 时有个「输出速度」选项（F1 是 2/10/50 MHz，F4 是 Low/Medium/High/Very High）。它<strong>不是输出频率的上限</strong>，而是<strong>驱动管翻转的快慢（压摆率）</strong>。</p><ul><li><strong>选太高</strong>：边沿陡峭 → 高频分量多 → EMI 辐射大，还可能引起信号过冲和串扰；</li><li><strong>选太低</strong>：边沿缓慢 → 高速通信（如 SPI 几十 MHz）时波形变形，接收端采样错误。</li></ul><p><strong>经验</strong>：点个 LED 选最低速；跑 UART 选低速或中速；跑 SPI 高速通信才选中/高速。原则是<strong>够用即可</strong>。</p><h2 id="五、驱动能力-什么时候必须加三极管" tabindex="-1">五、驱动能力：什么时候必须加三极管 <a class="header-anchor" href="#五、驱动能力-什么时候必须加三极管" aria-label="Permalink to &quot;五、驱动能力：什么时候必须加三极管&quot;">​</a></h2><p>STM32 单个 IO 的吸收/灌入电流一般限制在 <strong>20~25 mA</strong>，整片总电流也有上限（F103 约 150 mA）。几种典型负载：</p><table tabindex="0"><thead><tr><th>负载</th><th>能否直接驱动</th><th>说明</th></tr></thead><tbody><tr><td>普通指示 LED（5~10 mA）</td><td>✅ 可以</td><td>必须串限流电阻</td></tr><tr><td>蜂鸣器（有源，20 mA 以内）</td><td>✅ 勉强</td><td>建议仍用三极管</td></tr><tr><td>继电器线圈（70 mA 以上）</td><td>❌ 不行</td><td>必须用三极管/MOS</td></tr><tr><td>直流电机</td><td>❌ 不行</td><td>用 MOS 管或专用驱动芯片</td></tr><tr><td>大功率 LED / 灯带</td><td>❌ 不行</td><td>用 MOS 管</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">例 3 · 为什么开漏输出时 LED 不亮</p><p>有人把 LED（串电阻接 VCC，低电平点亮）接到配置成<strong>开漏输出</strong>的引脚上，写 1 期待 LED 灭、写 0 期待亮，结果<strong>写 1 时 LED 也亮了或者状态诡异</strong>。</p><p>原因是开漏写 1 = <strong>释放引脚</strong>，引脚变成高阻。此时：</p><ul><li>若外部有上拉电阻（或 LED+电阻接到 VCC 构成的通路），引脚被拉成高电平 → LED 两端无压差 → 灭；</li><li>若<strong>什么都没接</strong>，引脚悬空，电平不确定，LED 的状态也就不确定。</li></ul><p><strong>排查规则</strong>：用开漏输出时，先问一句「我的上拉电阻在哪里？」。没有上拉的开漏输出，永远得不到确定的高电平。这也是 I²C 总线必须接上拉电阻的原因（见 <a href="./spi-i2c">09 · SPI 与 I²C</a>）。</p></div><div class="tip custom-block"><p class="custom-block-title">例 4 · 用三极管驱动继电器，算基极电阻</p><p>继电器线圈 5 V、吸合电流 70 mA，用 NPN 三极管（如 S8050，取 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>h</mi><mrow><mi>F</mi><mi>E</mi></mrow></msub><mo>≈</mo><mn>100</mn></mrow><annotation encoding="application/x-tex">h_{FE} \\approx 100</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">h</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">F</span><span class="mord mathnormal mtight" style="margin-right:0.0576em;">E</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">100</span></span></span></span>）做低边开关，MCU 用 3.3 V IO 控制。</p><p><strong>第一步：算需要的基极电流</strong>（要让三极管饱和，工程上取理论值的 2~5 倍）：</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mi>I</mi><mrow><mi>B</mi><mo stretchy="false">(</mo><mi>m</mi><mi>i</mi><mi>n</mi><mo stretchy="false">)</mo></mrow></msub><mo>=</mo><mfrac><msub><mi>I</mi><mi>C</mi></msub><msub><mi>h</mi><mrow><mi>F</mi><mi>E</mi></mrow></msub></mfrac><mo>=</mo><mfrac><mn>70</mn><mn>100</mn></mfrac><mo>=</mo><mn>0.7</mn><mtext> mA</mtext><mo separator="true">,</mo><mspace width="2em"></mspace><mtext>取 3 倍</mtext><mo>≈</mo><mn>2.6</mn><mtext> mA</mtext></mrow><annotation encoding="application/x-tex">I_{B(min)} = \\frac{I_C}{h_{FE}} = \\frac{70}{100} = 0.7\\ \\text{mA},\\qquad \\text{取 3 倍} \\approx 2.6\\ \\text{mA} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0385em;vertical-align:-0.3552em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.5198em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0502em;">B</span><span class="mopen mtight">(</span><span class="mord mathnormal mtight">min</span><span class="mclose mtight">)</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3552em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.1963em;vertical-align:-0.836em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal">h</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">F</span><span class="mord mathnormal mtight" style="margin-right:0.0576em;">E</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0715em;">C</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.836em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.0074em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">100</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">70</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord">0.7</span><span class="mspace"> </span><span class="mord text"><span class="mord">mA</span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord cjk_fallback">取</span><span class="mord"> 3 </span><span class="mord cjk_fallback">倍</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">2.6</span><span class="mspace"> </span><span class="mord text"><span class="mord">mA</span></span></span></span></span></span><p><strong>第二步：算基极电阻</strong>（<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>V</mi><mrow><mi>B</mi><mi>E</mi></mrow></msub><mo>≈</mo><mn>0.7</mn></mrow><annotation encoding="application/x-tex">V_{BE} \\approx 0.7</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0502em;">B</span><span class="mord mathnormal mtight" style="margin-right:0.0576em;">E</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.7</span></span></span></span> V）：</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mi>R</mi><mi>B</mi></msub><mo>=</mo><mfrac><mrow><mn>3.3</mn><mo>−</mo><mn>0.7</mn></mrow><mrow><mn>2.6</mn><mtext> mA</mtext></mrow></mfrac><mo>≈</mo><mn>1000</mn><mtext> </mtext><mi mathvariant="normal">Ω</mi><mspace width="1em"></mspace><mtext>取标称 1 k</mtext><mi mathvariant="normal">Ω</mi></mrow><annotation encoding="application/x-tex">R_B = \\frac{3.3 - 0.7}{2.6\\ \\text{mA}} \\approx 1000\\ \\Omega \\quad \\text{取标称 1 k}\\Omega </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0502em;">B</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.0074em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">2.6</span><span class="mspace"> </span><span class="mord text"><span class="mord">mA</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">3.3</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord">0.7</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord">1000</span><span class="mspace"> </span><span class="mord">Ω</span><span class="mspace" style="margin-right:1em;"></span><span class="mord text"><span class="mord cjk_fallback">取标称</span><span class="mord"> 1 k</span></span><span class="mord">Ω</span></span></span></span></span><p><strong>验算</strong>：<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>R</mi><mi>B</mi></msub><mo>=</mo><mn>1</mn><mtext> k</mtext><mi mathvariant="normal">Ω</mi></mrow><annotation encoding="application/x-tex">R_B = 1\\ \\text{k}\\Omega</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0502em;">B</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord">1</span><span class="mspace"> </span><span class="mord text"><span class="mord">k</span></span><span class="mord">Ω</span></span></span></span> 时 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>I</mi><mi>B</mi></msub><mo>=</mo><mo stretchy="false">(</mo><mn>3.3</mn><mo>−</mo><mn>0.7</mn><mo stretchy="false">)</mo><mi mathvariant="normal">/</mi><mn>1000</mn><mo>=</mo><mn>2.6</mn></mrow><annotation encoding="application/x-tex">I_B = (3.3-0.7)/1000 = 2.6</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0502em;">B</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">3.3</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">0.7</span><span class="mclose">)</span><span class="mord">/1000</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2.6</span></span></span></span> mA，可驱动的集电极电流达 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>2.6</mn><mo>×</mo><mn>100</mn><mo>=</mo><mn>260</mn></mrow><annotation encoding="application/x-tex">2.6 \\times 100 = 260</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2.6</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">100</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">260</span></span></span></span> mA，远大于继电器所需的 70 mA → 三极管充分饱和。</p><p><strong>两个不能漏的元件</strong>：</p><ol><li><strong>续流二极管</strong>（反向并联在线圈两端）：继电器是电感，关断瞬间会产生很高的反向电动势，没有续流二极管会直接击穿三极管。</li><li><strong>基极下拉电阻</strong>（如 10 kΩ 到地）：保证 MCU 复位期间（IO 高阻）三极管不会误导通。</li></ol></div><h2 id="六、复用功能与重映射" tabindex="-1">六、复用功能与重映射 <a class="header-anchor" href="#六、复用功能与重映射" aria-label="Permalink to &quot;六、复用功能与重映射&quot;">​</a></h2><p>当引脚用作 UART、SPI、TIM 等外设功能时，必须配成<strong>复用模式</strong>，并且要<strong>开启 AFIO 时钟</strong>（F1 上重映射还需要操作 <code>AFIO-&gt;MAPR</code>）：</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">__HAL_RCC_AFIO_CLK_ENABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          // F1 上复用/重映射必须先开 AFIO 时钟</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 然后把引脚配成 GPIO_Mode_AF_PP（复用推挽）</span></span></code></pre></div><p><strong>忘了配复用是最常见的「外设没信号」原因</strong>：定时器在跑、代码也在执行，但引脚仍然是普通 GPIO，所以示波器上什么都看不到。</p><h2 id="七、工程实例" tabindex="-1">七、工程实例 <a class="header-anchor" href="#七、工程实例" aria-label="Permalink to &quot;七、工程实例&quot;">​</a></h2><p><strong>矩阵键盘</strong>：4×4 键盘只需要 8 根引脚（4 行 + 4 列），而不是 16 根。扫描方法是：把 4 行依次设为推挽输出低电平、其余高电平，同时读 4 列（配成上拉输入）；若某列读到 0，说明该行该列的按键被按下。用定时中断每 10 ms 扫一遍，顺便完成消抖。</p><p><strong>电平转换</strong>：3.3 V 的 MCU 要控制 5 V 器件时，把引脚配成<strong>开漏输出 + 外部上拉到 5 V</strong> 即可——输出 0 时拉低，输出 1 时由上拉电阻拉到 5 V。注意只有标注 <strong>FT</strong>（5 V 容忍）的引脚才能这样用，否则会损坏芯片。</p><h2 id="八、易错清单-自检" tabindex="-1">八、易错清单 + 自检 <a class="header-anchor" href="#八、易错清单-自检" aria-label="Permalink to &quot;八、易错清单 + 自检&quot;">​</a></h2><ul><li>[ ] <strong>输入引脚悬空</strong>：浮空输入 + 外部没接 = 读到随机值，必须配上拉或下拉</li><li>[ ] <strong>开漏输出没接上拉</strong>：写 1 得不到高电平</li><li>[ ] <strong>把「输出速度」当成输出频率上限</strong>：它其实是压摆率，选高了 EMI 大</li><li>[ ] <strong>用 IO 直接驱动继电器/电机</strong>：超过 20 mA 会烧引脚，必须加驱动管</li><li>[ ] <strong>驱动感性负载忘了续流二极管</strong>：关断时的反向电动势会击穿三极管</li><li>[ ] <strong>用外设却忘了配复用模式</strong>（以及 F1 上忘了开 AFIO 时钟）</li><li>[ ] <strong>按键没消抖</strong>：一次按下触发多次</li><li>[ ] <strong>用 <code>HAL_Delay</code> 做消抖</strong>：会阻塞整个程序，改用定时扫描</li></ul><p><strong>自检</strong>：要让一个按键「按下接地、松开为高」，引脚该配成什么模式？按键抖动一般持续多久？开漏输出要得到高电平必须加什么？（答案：上拉输入（或外部上拉 + 浮空输入）；5~20 ms；上拉电阻）</p>`,26))])}const w=i(g,[["render",d]]);export{E as __pageData,w as default};
